#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_timeSpeed;
uniform float amzp_glitchRate;
uniform float amzp_flickerThreshold;
uniform float amzp_seed;
uniform float amzp_tearHeightMin;
uniform float amzp_tearHeightRand;
uniform float amzp_tearOffsetMax;
uniform float amzp_tearScanFreq;
uniform float amzp_tearScanAmp;
uniform float amzp_bandMix;
uniform float amzp_blockGridMin;
uniform float amzp_blockGridRand;
uniform float amzp_blockGridY;
uniform float amzp_blockAffectThr;
uniform float amzp_staticProbThr;
uniform float amzp_enableColorBands;
uniform float amzp_bandProbThr;



    float random(float2 st) {
      return fract(sin(dot(st.xy, float2(12.9898, 78.233))) * 43758.5453123);
    }
    float2 random2(float2 st) {
      return float2( random(st), random(st + float2(1.0, 1.0)) );
    }

    void amzRender(){
      float2 fragCoord = amzScreenNorm() * screen.zw;
      float2 uv = amzScreenNorm();
      float4 originalColor = amzTexture(0, uv);


      float t = floor((time * amzp_timeSpeed + amzp_seed*0.001) * amzp_glitchRate);
      float glitchTrigger = random(float2(t, 0.0));

      if (glitchTrigger > amzp_flickerThreshold) {

        float tearY = random(float2(t, 2.0));
        float tearHeight = amzp_tearHeightMin + random(float2(t, 3.0)) * amzp_tearHeightRand;
        float tearOffset = (random(float2(t, 4.0)) - 0.5) * (amzp_tearOffsetMax*2.0);

        if (uv.y > tearY && uv.y < tearY + max(tearHeight, 0.0)) {
          float isColorBand = random(float2(t, 5.0));
          if ((amzp_enableColorBands>0.5) && isColorBand > amzp_bandProbThr) {
            float2 duv = uv; duv.x = fract(duv.x + tearOffset);
            float4 displacedColor = amzTexture(0, duv);

            float3 bandColor = float3(
              random(float2(t, 6.0)),
              random(float2(t, 7.0)),
              random(float2(t, 8.0))
            );
            displacedColor.rgb = mix(displacedColor.rgb, bandColor, clamp(amzp_bandMix,0.0,1.0));


            float scanLine = sin(fragCoord.y * amzp_tearScanFreq) * amzp_tearScanAmp;
            displacedColor.rgb = clamp(displacedColor.rgb - scanLine, 0.0, 1.0);
            originalColor = displacedColor;
          } else {
            float2 duv = uv; duv.x = fract(duv.x + tearOffset);
            originalColor = amzTexture(0, duv);
          }
        }


        float gridX = amzp_blockGridMin + random(float2(t, 9.0)) * amzp_blockGridRand;
        float2 blockGrid = floor(uv * float2(max(1.0, gridX), max(1.0, amzp_blockGridY)));
        float blockTrigger = random(blockGrid + t);
        if (blockTrigger > amzp_blockAffectThr) {
          float blockType = random(blockGrid + 10.0 + t);
          if (blockType > amzp_staticProbThr) {

            float2 sc = fract(uv * 10.0);
            originalColor.rgb = clamp(float3(
              random(sc),
              random(sc.yx),
              random(uv)
            ), 0.0, 1.0);
          } else {

            float2 ro = (random2(blockGrid + 23.0) - 0.5) * 2.0;
            originalColor = amzTexture(0, fract(uv + ro));
          }
        }
      }

      amzOutput = originalColor;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

